  // Pixflow interface copy.
  "wp.message.26a6374fbf59": "Ein Pixflow-Add-on konnte nicht starten. Prüfe die Kompatibilität deiner Pixflow-Plugins und lade neu. Andere Funktionen sind möglicherweise weiterhin verfügbar.",
  "wp.message.ca7714cffbcc": "Pro aktivieren",
  "wp.message.197c83a2f752": "Hole deine Premium-Werkzeuge mit dem Pro-Add-on zurück. Lizenz, Inhalte und gespeicherte Einstellungen bleiben erhalten. Falls du die Bricks-Zwei-Faktor-Authentifizierung verwendet hast, aktiviere sie nach der Pro-Aktivierung wieder in den Einstellungen.",
  "wp.message.2ffdcbc380ea": "Arbeite in deinem bevorzugten Builder. Ergänze deinen Workflow um Anmerkungen, Sprachfunktionen, Designsysteme und Bilderstellung.",
  "wp.message.40ed1102964b": "Pro-Test prüfen",
  "wp.message.e9cccd3ef5fc": "Das Ausblenden konnte nicht gespeichert werden. Bitte versuche es erneut.",
  "wp.message.1372089fb797": "Pixflow Pro-Banner schließen",
  "wp.message.5e3ba715018d": "Pro herunterladen",
  "wp.message.fb2e6d87b44c": "Mehr Möglichkeiten mit Pixflow Design Pro",
  "wp.message.9934717ca744": "Aktualisiere diese Seite und versuche es erneut.",
  "wp.message.7c78f9990490": "Deinen 7-tägigen Pro-Test starten",
  "wp.message.f89b4dcf2c2e": "Pro 7 Tage testen",
