  "ui.finalOnboarding.f54f5d4bcd": "Deine Einrichtung",
  "ui.finalOnboarding.7d2d594053": "Wie möchtest du Pixflow nutzen?",
  "ui.finalOnboarding.bdf73477f9": "Verbinde deinen API-Anbieter",
