  "ui.finalOnboarding.f9573d1164": "Du kannst loslegen",
  "ui.finalOnboarding.45ddd1221b": "Die Bearbeitung mit WordPress und Gutenberg ist kostenlos. Du brauchst weder Lizenz noch Testversion.",
  "ui.finalOnboarding.6072f06060": "Aktiviere deine Lizenz, um zu beginnen. Bereits aktiviert? Deine Lizenz erscheint hier.",
