  "ui.mediaStarter.image1.title": "Editorial-Porträt",
  "ui.mediaStarter.image1.tag": "Porträt",
  "ui.mediaStarter.image1.prompt": "Ein Editorial-Nahporträt einer kreativen Leitung Ende 20, weiches Tageslicht durch hohe Studiofenster, warme neutrale Palette (Creme, Taupe, sanftes Schwarz), aufgenommen mit 85 mm bei f/1.8 und geringer Schärfentiefe, klarer Blick direkt in die Kamera, dezentes Filmkorn, ungeschminkter Look.",
  "ui.mediaStarter.image2.title": "Produkt-Hauptmotiv",
  "ui.mediaStarter.image2.tag": "E-Commerce",
  "ui.mediaStarter.image2.prompt": "Ein hochwertiges Hauptmotiv einer einzelnen matten Keramik-Kaffeetasse vor warmem cremefarbenem Papier. Hartes Kantenlicht von links oben, sanfter langer Schatten nach rechts unten, zarter Dampf über der Tasse. Quadratischer Ausschnitt, zentrierte Komposition, Platz für eine Überschrift darüber, keine Requisiten oder Hände im Bild.",
  "ui.mediaStarter.image3.title": "Flache Illustration",
  "ui.mediaStarter.image3.tag": "Illustration",
  "ui.mediaStarter.image3.prompt": "Eine flache Vektorillustration einer gemütlichen Leseecke an einem verregneten Fenster: geometrische Formen, zurückhaltende Palette aus fünf Farben (Creme, Terrakotta, dunkles Petrol, gebrannte Siena, sanftes Schwarz), feine 1.5px-Linien, keine Verläufe oder Texturen, weiche Schlagschatten nur am Sessel im Vordergrund.",
  "ui.mediaStarter.video1.title": "Produktenthüllung",
  "ui.mediaStarter.video1.tag": "Filmisch",
  "ui.mediaStarter.video1.prompt": "Eine Produktenthüllung von 5 Sekunden: eine minimalistische hochwertige Hautpflegeflasche auf sauberem cremefarbenem Stein, weiches Seitenlicht von links, langsame Kamerafahrt nach vorn, dezente Fokusverlagerung vom Deckel zum Etikett, zurückhaltende Bewegung, keine Texteinblendungen oder Menschen.",
  "ui.mediaStarter.video2.title": "Laternen-Nahaufnahme",
  "ui.mediaStarter.video2.tag": "Stimmung",
  "ui.mediaStarter.video2.prompt": "Eine filmische Nahaufnahme von 6 Sekunden: eine junge Frau hält eine leuchtende Papierlaterne in einem nebligen Kiefernwald zur goldenen Stunde. Geringe Schärfentiefe auf ihren Augen, sanfte Kamerafahrt nach vorn, Partikel im warmen Lichtstrahl, kein Dialog, nur Waldgeräusche.",
  "ui.mediaStarter.video3.title": "Drift in Neonstraßen",
  "ui.mediaStarter.video3.tag": "Action",
  "ui.mediaStarter.video3.prompt": "Eine 5-sekündige Verfolgungsaufnahme eines nächtlichen Straßenrennens in einer neonbeleuchteten Cyberpunk-Gasse in Hongkong. Tiefe Kamera folgt einem mattschwarzen Sportwagen beim Drift um eine enge Kurve, Bewegungsunschärfe an den Rädern, Lens Flares von Neonreklamen, regennasser Asphalt mit Lichtreflexen, kein Bildschirmtext.",
  "ui.mediaStarter.hyperframes1.title": "Enthüllung mit Lupe",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "Erstelle eine 5-sekündige Komposition mit einer einzelnen fetten Display-Textzeile auf einer sauberen Fläche. Animiere eine runde Lupe, die von links nach rechts darüber wandert und die Buchstaben durch dezente Glasbrechung verformt. Nutze HyperFrames html-in-canvas: Erfasse das Text-DOM und lege einen Linsenshader mit einem Durchlauf im Stil von vfx-liquid-glass darüber. Reines CSS für den Text; das Glas ist eine WebGL-Ebene.",
  "ui.mediaStarter.hyperframes2.title": "CRT-Terminalszene",
  "ui.mediaStarter.hyperframes2.tag": "Retro-VFX",
  "ui.mediaStarter.hyperframes2.prompt": "Erstelle eine CRT-Bildschirmkomposition: dunkle Fläche, Terminaltext in Festbreitenschrift tippt `npx hyperframes init my-video`, dann wird `claude` mit dem Prompt „Füge einen CRT-Effekt mit HTML-in-canvas hinzu“ aufgerufen. Lege über das Live-DOM per html-in-canvas einen dezenten Wölbungsshader, Scanlines, leichte chromatische Aberration und sanftes Phosphorleuchten. Der Terminaltext bleibt echtes CSS und ist vor dem Shaderdurchlauf pixelscharf.",
  "ui.mediaStarter.hyperframes3.title": "Glitch-Zerfall",
  "ui.mediaStarter.hyperframes3.tag": "Glitch",
  "ui.mediaStarter.hyperframes3.prompt": "Erstelle eine 6-sekündige Komposition mit Hauptüberschrift und einzeiligem Untertitel auf dunkler Fläche, die dann in einen harten digitalen Glitch zerfällt: RGB-Kanaltrennung, horizontale Versatzbänder, kurzes Bildstottern und ein sauberer Reset am Ende. Erfasse das Live-DOM per html-in-canvas und lege den Glitch darüber, sodass die Schrift unter dem Shader echtes CSS bleibt.",
  "ui.mediaStarter.audio1.title": "Marken-Voiceover",
  "ui.mediaStarter.audio1.tag": "Sprache",
  "ui.mediaStarter.audio1.prompt": "Ein warmes erzählerisches Voiceover von 30 Sekunden für ein Produktlaunch-Video: selbstbewusst und gesprächig, mittleres Tempo, kurze Pause nach dem Markennamen. Text: 'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' Englisch mit neutralem nordamerikanischem Akzent.",
  "ui.mediaStarter.audio2.title": "Einführungsnarration",
  "ui.mediaStarter.audio2.tag": "Sprache",
  "ui.mediaStarter.audio2.prompt": "Eine freundliche Einführungsnarration von 20 Sekunden für den ersten Start einer mobilen App. Beruhigender, lächelnder Ton, aufmerksam langsam, ohne abgelesen zu klingen. Text: „Willkommen bei Loop. Richten wir deinen Bereich ein: drei kurze Fragen und du bist dabei. Du kannst später alles ändern.“",
  "ui.mediaStarter.audio3.title": "Geschichtenpassage",
  "ui.mediaStarter.audio3.tag": "Sprache",
  "ui.mediaStarter.audio3.prompt": "Eine filmische Lesung eines Einstiegsabschnitts von 45 Sekunden. Tiefer, ruhiger Vortrag mit Atempausen zwischen Sätzen, leicht intime Nahmikrofonwirkung. Text: „Die Stadt schläft in Stücken. Eine Neonreklame flackert über dem Ramen-Tresen. Auf der anderen Straßenseite leuchtet ein Fenster: das einzige, das diesseits von Mitternacht noch an ist.“",
